// src/lib/credential-delivery.ts — Canonical Delivery Kind Classification & URL Validation
// Enforces strict security invariants:
// 1. Invalid/relative strings (e.g. "TIGER") never become clickable activation links.
// 2. Clear distinction between accounts, plain access text, activation URLs, and missing data.
// 3. Exact unit-level data binding for display and clipboard copy.

export type DeliveryKind = "account" | "access_text" | "activation_link" | "missing";

/**
 * Validates whether a candidate string is an absolute http(s) URL.
 * Rejects relative strings (e.g. "/TIGER", "TIGER"), javascript:, data:, and plain text.
 */
export function isValidActivationUrl(url: string | null | undefined): boolean {
  if (!url || typeof url !== "string") return false;
  const trimmed = url.trim();
  if (trimmed.length < 8) return false;
  try {
    const parsed = new URL(trimmed);
    return parsed.protocol === "https:" || parsed.protocol === "http:";
  } catch {
    return false;
  }
}

export interface UnitDeliverySource {
  format?: string | null;
  label?: string | null;
  email?: string | null;
  password?: string | null;
  accountUrl?: string | null;
  rawPayload?: string | null;
}

/**
 * Classifies a unit delivery into its authoritative delivery kind.
 */
export function getDeliveryKind(cred: UnitDeliverySource): DeliveryKind {
  // 1. Activation Link: Must have a validated absolute http(s) URL
  if (isValidActivationUrl(cred.accountUrl)) {
    return "activation_link";
  }
  if (isValidActivationUrl(cred.rawPayload)) {
    return "activation_link";
  }

  // 2. Account: Explicit username/email AND password
  if (cred.email && cred.password) {
    return "account";
  }
  if (cred.format === "account" && (cred.email || cred.password)) {
    return "account";
  }

  // 3. Check rawPayload or combined text
  const textContent = cred.rawPayload || cred.password || cred.email;
  if (
    textContent &&
    textContent !== "[NO_PAYLOAD]" &&
    textContent !== "[NO_CREDENTIALS_STORED]" &&
    !textContent.startsWith("v1:") &&
    !textContent.startsWith("v2:")
  ) {
    // If it looks like user:pass with @
    if (textContent.includes(":") && textContent.includes("@") && !textContent.startsWith("http")) {
      return "account";
    }
    return "access_text";
  }

  return "missing";
}

/**
 * Computes the authoritative clipboard copy text for a given unit and kind.
 */
export function getUnitCopyValue(cred: UnitDeliverySource, kind: DeliveryKind): string {
  switch (kind) {
    case "activation_link":
      return cred.accountUrl?.trim() || (isValidActivationUrl(cred.rawPayload) ? cred.rawPayload!.trim() : "");
    case "account":
      if (cred.email && cred.password) {
        return `${cred.email.trim()}:${cred.password.trim()}`;
      }
      return (cred.password || cred.email || cred.rawPayload || "").trim();
    case "access_text":
      return (cred.rawPayload || cred.password || cred.email || "").trim();
    case "missing":
    default:
      return "";
  }
}
